const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={stage:0,waterings:0,pollen:false,pollinated:false,bagged:false,ripe:false,harvested:false,labStep:0,slideReady:false,focus:25,mag:40,light:65,seenLow:false,seenHigh:false,identified:false,sound:true};
let toastTimer;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function showModal(title,copy){$('#modalTitle').textContent=title;$('#modalCopy').textContent=copy;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function setTask(n,title,copy,button,action){$('#taskTitle').textContent=title;$('#taskText').textContent=copy;$('#taskCheck').textContent=`${n}/4`;$('#taskAction').innerHTML=button?`<button class="primary-btn" id="dynamicTaskBtn">${button} <span>↗</span></button>`:'';if(action&&$('#dynamicTaskBtn'))$('#dynamicTaskBtn').addEventListener('click',action);$('#journeyLabel').textContent=`Step ${n} of 4`;$('#journeyProgress').style.width=`${[7,30,58,81,100][n]}%`}
function updateDay(n=1){const d=Number($('#dayCount').textContent)+n;$('#dayCount').textContent=String(d).padStart(2,'0')}
function setGardenStage(stage){state.stage=stage;const plant=$('#plantArt');plant.classList.remove('stage-seedling','stage-growing','stage-bloom');if(stage===1)plant.classList.add('stage-seedling');if(stage===2)plant.classList.add('stage-growing');if(stage>=3)plant.classList.add('stage-bloom');$('#seedMound').style.display=stage===0?'flex':'none';if(stage===0){setTask(0,'Plant your first seed','Every luffa begins with a seed. Give yours a home in the garden bed.','Plant luffa seed',plantSeed)}if(stage===1){setTask(1,'Help your seedling grow','A little water and a few sunny days will bring your vine to life.','Water the seedling',waterPlant)}if(stage===2){setTask(1,'A healthy vine is growing','Your plant is stretching up the trellis. Give it one more drink of water.','Water the vine',waterPlant)}if(stage===3){setTask(2,'Meet the flowers','The male bloom makes pollen. Pick up a little with your soft brush.','',null);$('#taskText').textContent='Tap the male flower to collect pollen, then transfer it to the female flower. Try bagging the bloom first for a controlled pollination.';$('#taskCheck').textContent='2/4';$('#toolHint').textContent='Brush tool: tap the male flower, then the female stigma. Bag tool: protect an unpollinated bloom.'}if(stage===4){setTask(3,'Pollination complete!','Pollen reached the stigma. Give your tiny fruit a few days to swell.','Fast-forward 3 days',advanceFruit)}if(stage>=5){setTask(4,'Your luffa is ready','Harvest your ripe fruit to see the seeds—and unlock the microscope lab.','Harvest luffa',harvestFruit)}$('#gardenStatus').textContent=state.harvested?'COMPLETE':'IN PROGRESS';}
function plantSeed(){setGardenStage(1);toast('Seed planted. Let’s help it grow!')}
function waterPlant(){state.waterings++;updateDay(2);if(state.waterings===1){setGardenStage(2);$('#plantArt').style.transform='scale(1.05)';toast('Sunshine and water—your vine is thriving.')}else{setGardenStage(3);$('#plantArt').style.transform='';toast('Golden blooms! Your male and female flowers are open.')}}
function setTool(tool){$$('.tool').forEach(x=>x.classList.toggle('active',x.dataset.tool===tool));$('#toolHint').textContent=tool==='bag'?'Bag tool: tap the female flower to protect it; tap again to unbag before pollinating.':'Brush tool: tap the male flower, then the female stigma.'}
function handleFlower(which){if(state.stage<3){toast('The flowers are not open yet. Keep tending your vine.');return}if(state.pollinated){toast('This bloom has already been pollinated.');return}if($('[data-tool="bag"]').classList.contains('active')){if(which!=='female'){toast('Flower bags protect female blooms.');return}state.bagged=!state.bagged;$('#femaleFlower').classList.toggle('bagged',state.bagged);toast(state.bagged?'Female flower bagged—outside pollen is kept out.':'Bag removed. You can pollinate this flower now.');return}if(which==='male'){state.pollen=true;$('#maleFlower').classList.add('pollinated');toast('Pollen collected! Now tap the female flower.');return}if(!state.pollen){toast('First collect pollen from the male flower.');return}if(state.bagged){toast('Remove the flower bag before transferring pollen.');return}state.pollen=false;state.pollinated=true;$('#femaleFlower').classList.add('pollinated');$('#plantArt').classList.add('pollinated');$('#taskCheck').textContent='3/4';setTimeout(()=>{if(state.stage===3)setGardenStage(4)},500);toast('Pollinated! Pollen has reached the stigma.');$('#taskTitle').textContent='A tiny fruit is forming';$('#taskText').textContent='The flower is fading and the ovary is swelling. Advance a few days to see what grows.';$('#taskAction').innerHTML='<button class="primary-btn" id="dynamicTaskBtn">Fast-forward 3 days <span>↗</span></button>';$('#dynamicTaskBtn').addEventListener('click',advanceFruit)}
function advanceFruit(){if(!state.pollinated){toast('Pollinate a female flower first.');return}updateDay(3);state.ripe=true;$('#fruitArt').classList.add('visible','ripe');$('#femaleFlower').style.opacity='.35';$('#gardenBed').classList.add('fruit-time');setGardenStage(5);toast('Time-lapse complete! Your luffa is ripe.');}
function harvestFruit(){if(!state.ripe)return;state.harvested=true;$('#fruitArt').classList.remove('visible');$('#seedMound').style.display='flex';$('#seedMound').innerHTML='<span></span><span></span><span></span><small>SEEDS FROM YOUR LUFFA</small>';$('#plantArt').style.opacity='.78';$('#labTab').classList.remove('locked');$('#labTab').classList.add('unlocked');$('#labStatus').textContent='UNLOCKED';$('#gardenStatus').textContent='COMPLETE';$('#sampleCount').textContent='01';setTask(4,'A harvest full of possibility','Your fruit holds seeds for the next growing cycle. Your pollen sample is ready in the lab.','',null);$('#taskText').textContent='You grew a luffa with seeds inside. The Luffa Lab is now open—prepare a wet-mount slide and find a pollen grain.';$('#taskCheck').textContent='4/4';toast('Harvest collected! Luffa Lab unlocked.');$('#labTab').onclick=()=>switchView('lab')}
function switchView(view){if(view==='lab'&&!state.harvested){toast('Harvest your first luffa to unlock the lab.');return}const lab=view==='lab';$('#gardenView').classList.toggle('hidden',lab);$('#labView').classList.toggle('hidden',!lab);$('#gardenTab').classList.toggle('active',!lab);$('#labTab').classList.toggle('active',lab);window.scrollTo({top:0,behavior:'smooth'})}
const labSteps=[
 {title:'Add a drop of water',copy:'A wet mount helps light pass through the sample. Click the dropper to add one drop.',kicker:'PREPARE YOUR SLIDE',button:'Add water drop'},
 {title:'Collect a little pollen',copy:'Use the cotton swab to gently pick up pollen from your harvested flower.',kicker:'GATHER YOUR SPECIMEN',button:'Collect pollen'},
 {title:'Place pollen on the slide',copy:'Dab the pollen into the water drop at the center of the clean slide.',kicker:'MAKE YOUR WET MOUNT',button:'Place pollen'},
 {title:'Lower the cover glass',copy:'Lower the cover glass slowly from one side. This pushes air out and helps prevent bubbles.',kicker:'NO AIR BUBBLES',button:'Lower cover glass'},
 {title:'Secure the slide',copy:'Click both stage clips to hold your finished wet mount in place.',kicker:'READY THE MICROSCOPE',button:'Fix slide clips'}
];
function renderLabStep(){const i=state.labStep;$('#labStepLabel').textContent=i<5?`SLIDE PREPARATION · STEP ${i+1}/5`:'MICROSCOPE OBSERVATION · FIND THE GRAIN';$('#labProgressBar').style.width=`${Math.min(i,5)/6*100}%`;$('#labInstruction').textContent=i<5?labSteps[i].title:'Find a pollen grain';$('#labInstructionCopy').textContent=i<5?labSteps[i].copy:'Adjust the light and focus. Compare low and high magnification, then click the golden pollen grain to identify it.';$('#instructionKicker').textContent=i<5?labSteps[i].kicker:'YOUR LUFFA SAMPLE';$('#instructionNumber').textContent=String(Math.min(i+1,6)).padStart(2,'0');$('#bench').classList.toggle('lab-complete',i>=5);$('#labActionBtn').textContent=i<5?labSteps[i].button:'Slide prepared';$('#labActionBtn').disabled=i>=5;$('#labActionBtn').innerHTML=(i<5?labSteps[i].button:'Slide prepared')+(i<5?' <span>↗</span>':'');$('#dropper').style.display=i===0?'block':'none';$('#labSwab').style.display=i===1?'block':'none';$('#coverTool').style.display=i===3?'block':'none';$('#waterDrop').style.display=i>=1?'block':'none';$('#sampleDots').style.display=i>=3?'block':'none';$('#coverGlass').style.display=i>=4?'block':'none';$('.label-swab').style.display=i===1?'block':'none';$('.label-dropper').style.display=i===0?'block':'none';$('#scopeOverlay').style.display=i>=5?'none':'grid';if(i>=5){$('#scopeOverlay').innerHTML='SLIDE READY<br><small>ADJUST FOCUS TO BEGIN</small>'}$('#labActionBtn').onclick=()=>advanceLab()}
function advanceLab(){if(state.labStep>=5)return;const i=state.labStep;if(i===0){$('#waterDrop').style.display='block';$('#dropper').animate([{transform:'rotate(26deg) translateY(0)'},{transform:'rotate(26deg) translateY(28px)'},{transform:'rotate(26deg) translateY(0)'}],{duration:500});toast('A drop of water is on the slide.')}if(i===1){$('#labSwab').animate([{transform:'rotate(49deg) translateY(0)'},{transform:'rotate(49deg) translateY(35px)'},{transform:'rotate(49deg) translateY(0)'}],{duration:500});toast('Pollen collected on your cotton swab.')}if(i===2){$('#sampleDots').style.display='block';toast('Pollen dabbed into the water.')}if(i===3){const glass=$('#coverGlass');glass.style.display='block';glass.animate([{transform:'translate(-80px,-26px)',opacity:.4},{transform:'translate(0,0)',opacity:1}],{duration:650,easing:'ease-out'});toast('Cover glass lowered from one side—no bubbles!')}if(i===4){$('#scopeOverlay').textContent='SLIDE FIXED';setTimeout(()=>{$('#scopeOverlay').style.display='none'},600);state.slideReady=true;toast('Slide secured. Your microscope is ready.')}state.labStep++;renderLabStep()}
function updateFocus(delta,kind){if(state.labStep<5){toast('Prepare and secure your slide first.');return}state.focus=Math.max(0,Math.min(100,state.focus+delta));$('#focusMeter').style.width=state.focus+'%';const grain=$('#pollenGrain');const sharp=Math.max(0,1-Math.abs(state.focus-62)/62);grain.style.filter=`blur(${(1-sharp)*5}px)`;grain.style.opacity=String(.25+sharp*.75);if(state.focus<10){showModal('Objective too close!','The objective lens is nearly touching the slide. Lower the stage before continuing—on a real microscope, contact can break the slide.');state.focus=15;$('#focusMeter').style.width='15%'}if(Math.abs(state.focus-62)<12){$('#scopeOverlay').style.display='none';grain.style.display='block';if(state.mag===40)state.seenLow=true;if(state.mag===100)state.seenHigh=true;toast(kind==='fine'?'Fine focus—look at that pollen grain!':'Image is coming into focus. Use fine focus to sharpen it.')}else if(state.focus>25){$('#scopeOverlay').style.display='none';grain.style.display='block'}else{$('#scopeOverlay').style.display='grid';$('#scopeOverlay').innerHTML='IMAGE OUT OF FOCUS<br><small>TURN THE FOCUS KNOBS</small>'}}
function setMag(m){state.mag=Number(m);$('#magReadout').textContent=m+'×';$('#objectiveReadout').textContent=(Number(m)/10)+'×';$('#totalReadout').textContent=m+'×';$$('.mag-btn').forEach(b=>b.classList.toggle('active',b.dataset.mag===String(m)));if(state.labStep>=5){if(m==='40')state.seenLow=true;else state.seenHigh=true;const grain=$('#pollenGrain');grain.style.transform=`rotate(-25deg) scale(${m==='100'?2.15:1})`;$('#scopeScreen').style.filter=`brightness(${.6+state.light/100*.65}) saturate(${m==='100'?1.25:1})`;if(Math.abs(state.focus-62)<18)toast(m==='100'?'High power: a closer look at the pollen.':'Low power: a wider view of the specimen.')}}
$('#plantBtn').onclick=plantSeed;$('#brushTool').onclick=()=>setTool('brush');$('#bagTool').onclick=()=>setTool('bag');$('#maleFlower').onclick=()=>handleFlower('male');$('#femaleFlower').onclick=()=>handleFlower('female');$$('.tool').forEach(el=>{el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.tool));$('#gardenBed').addEventListener('dragover',e=>e.preventDefault());$('#gardenBed').addEventListener('drop',e=>{e.preventDefault();const tool=e.dataTransfer.getData('text/plain');if(tool)setTool(tool);const target=document.elementFromPoint(e.clientX,e.clientY);if(target?.closest('.female-flower'))handleFlower('female');else if(target?.closest('.male-flower'))handleFlower('male')})});$('#gardenTab').onclick=()=>switchView('garden');$('#labTab').onclick=()=>switchView('lab');$('#labActionBtn').onclick=advanceLab;$('#coarseFocus').onclick=()=>updateFocus(-15,'coarse');$('#fineFocus').onclick=()=>updateFocus(7,'fine');$$('.mag-btn').forEach(b=>b.onclick=()=>setMag(b.dataset.mag));$('#lightSlider').oninput=e=>{state.light=Number(e.target.value);$('#lightReadout').textContent=state.light+'%';$('#scopeScreen').style.filter=`brightness(${.6+state.light/100*.65}) saturate(${state.mag===100?1.25:1})`};$('#pollenGrain').onclick=()=>{if(state.labStep<5||Math.abs(state.focus-62)>17){toast('Bring the grain into sharp focus first.');return}state.identified=true;$('#pollenGrain').classList.add('identified');$('#labInstruction').textContent='Pollen grain identified!';$('#labInstructionCopy').textContent='You found it: an oval, golden pollen grain. At high magnification it looks larger; the image is inverted through the eyepiece.';$('#instructionKicker').textContent='SPECIMEN IDENTIFIED';$('#instructionNumber').textContent='✦';$('#labProgressBar').style.width='100%';$('#labStepLabel').textContent='OBSERVATION COMPLETE';$('#scopeOverlay').style.display='grid';$('#scopeOverlay').innerHTML='GRAIN IDENTIFIED<br><small>OVAL · GOLDEN YELLOW</small>';toast('Excellent observation! Pollen grain identified.');setTimeout(()=>showModal('Field note complete','You prepared a wet mount, secured the slide, and observed an oval, yellow pollen grain. Magnification makes the specimen appear larger; the microscope image is inverted and reversed.'),700)};
$('#helpBtn').onclick=()=>showModal('Pollination, simply','Pollen must travel from a male flower’s anther to a female flower’s stigma. Once pollinated, the flower can develop into a fruit containing seeds. Bagging keeps other pollen away so you can control the transfer.');$('#modalClose').onclick=closeModal;$('#modalOkay').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#soundToggle').onclick=()=>{state.sound=!state.sound;$('#soundToggle').innerHTML=state.sound?'♫ <span>Sound on</span>':'♫ <span>Sound off</span>';toast(state.sound?'Sound on':'Sound off')};
// Dragging tools gives the same pollination actions as tapping, making the garden comfortable on desktop and touch screens.
$$('.tool').forEach(el=>el.addEventListener('dragend',()=>$('#gardenBed').classList.remove('drag-over')));$('#gardenBed').addEventListener('dragenter',()=>$('#gardenBed').classList.add('drag-over'));$('#gardenBed').addEventListener('dragleave',e=>{if(!e.relatedTarget||!$('#gardenBed').contains(e.relatedTarget))$('#gardenBed').classList.remove('drag-over')});
setGardenStage(0);renderLabStep();

